"""Thin wrapper around the fastText engine."""
import fasttext


def train_supervised(input_path, output_path, **kwargs):
    """Train a supervised fastText model."""
    model = fasttext.train_supervised(input=input_path, **kwargs)
    model.save_model(output_path)
    return model


def test_model(model, test_path):
    """Test a fastText model and return (n_samples, precision, recall)."""
    return model.test(test_path)


def load_model(model_path):
    return fasttext.load_model(model_path)
